#include <memory>
#include <mutex>
#include <atomic>
#include <functional>
#include <vector>
#include <chrono>
#include <thread>
#include <queue>
#include <string>
#include <cstring>

namespace rt_chat {

enum class CircuitState { CLOSED, OPEN, HALF_OPEN };

struct Message {
    char* payload;
    size_t len;
    uint64_t seq_id;

    Message(const char* data, size_t n, uint64_t id) : len(n), seq_id(id) {
        payload = new char[n + 1];
        memcpy(payload, data, n);
        payload[n] = '\0';
    }

    ~Message() { delete[] payload; }

    Message(const Message& o) : len(o.len), seq_id(o.seq_id) {
        payload = new char[len + 1];
        memcpy(payload, o.payload, len + 1);
    }

    Message& operator=(const Message& o) {
        if (this != &o) {
            delete[] payload;
            len = o.len;
            seq_id = o.seq_id;
            payload = new char[len + 1];
            memcpy(payload, o.payload, len + 1);
        }
        return *this;
    }

    Message(Message&& o) noexcept : payload(o.payload), len(o.len), seq_id(o.seq_id) {
        o.payload = nullptr;
        o.len = 0;
    }

    Message& operator=(Message&& o) noexcept {
        if (this != &o) {
            delete[] payload;
            payload = o.payload;
            len = o.len;
            seq_id = o.seq_id;
            o.payload = nullptr;
            o.len = 0;
        }
        return *this;
    }
};

class CircuitBreaker {
    std::atomic<CircuitState> state_{CircuitState::CLOSED};
    std::atomic<int> failure_count_{0};
    std::atomic<int> success_count_{0};
    int failure_threshold_;
    int recovery_threshold_;
    std::chrono::steady_clock::time_point open_time_;
    std::chrono::milliseconds timeout_;
    std::mutex state_mutex_;

public:
    CircuitBreaker(int fail_thresh = 3, int recover_thresh = 2,
                   std::chrono::milliseconds timeout = std::chrono::milliseconds(5000))
        : failure_threshold_(fail_thresh), recovery_threshold_(recover_thresh),
          timeout_(timeout) {}

    bool allow_request() {
        auto current = state_.load(std::memory_order_acquire);
        if (current == CircuitState::CLOSED) return true;
        if (current == CircuitState::OPEN) {
            std::lock_guard<std::mutex> lock(state_mutex_);
            auto now = std::chrono::steady_clock::now();
            if (now - open_time_ >= timeout_) {
                state_.store(CircuitState::HALF_OPEN, std::memory_order_release);
                return true;
            }
            return false;
        }
        return true; // HALF_OPEN allows probe requests
    }

    void record_success() {
        auto current = state_.load(std::memory_order_acquire);
        if (current == CircuitState::HALF_OPEN) {
            if (++success_count_ >= recovery_threshold_) {
                std::lock_guard<std::mutex> lock(state_mutex_);
                state_.store(CircuitState::CLOSED, std::memory_order_release);
                failure_count_.store(0, std::memory_order_release);
                success_count_.store(0, std::memory_order_release);
            }
        } else {
            failure_count_.store(0, std::memory_order_release);
        }
    }

    void record_failure() {
        success_count_.store(0, std::memory_order_release);
        if (++failure_count_ >= failure_threshold_) {
            std::lock_guard<std::mutex> lock(state_mutex_);
            state_.store(CircuitState::OPEN, std::memory_order_release);
            open_time_ = std::chrono::steady_clock::now();
        }
    }

    CircuitState get_state() const { return state_.load(std::memory_order_acquire); }
};

class MessageRouter {
    struct PendingDelivery {
        Message* msg;
        int retry_count;
        bool ownership_transferred;
    };

    std::vector<PendingDelivery> pending_;
    CircuitBreaker& breaker_;
    std::mutex queue_mutex_;

public:
    MessageRouter(CircuitBreaker& cb) : breaker_(cb) {}

    void enqueue(Message* msg) {
        std::lock_guard<std::mutex> lock(queue_mutex_);
        pending_.push_back({msg, 0, false});
    }

    void process_batch() {
        std::lock_guard<std::mutex> lock(queue_mutex_);
        std::vector<size_t> completed;

        for (size_t i = 0; i < pending_.size(); ++i) {
            auto& entry = pending_[i];
            if (!breaker_.allow_request()) {
                entry.retry_count++;
                if (entry.retry_count > 5) {
                    // Circuit is open too long, discard message
                    if (!entry.ownership_transferred) {
                        delete entry.msg;
                    }
                    completed.push_back(i);
                }
                continue;
            }

            bool success = try_deliver(entry.msg);
            if (success) {
                breaker_.record_success();
                entry.ownership_transferred = true;
                completed.push_back(i);
            } else {
                breaker_.record_failure();
                entry.retry_count++;
                if (entry.retry_count > 5) {
                    if (!entry.ownership_transferred) {
                        delete entry.msg;
                    }
                    completed.push_back(i);
                }
            }
        }

        // Remove completed entries in reverse order
        for (auto it = completed.rbegin(); it != completed.rend(); ++it) {
            pending_.erase(pending_.begin() + *it);
        }
    }

private:
    bool try_deliver(Message* msg) {
        // Simulate delivery - in real code this sends over network
        return msg->seq_id % 7 != 0; // Simulate occasional failures
    }
};

class ChatSession {
    std::vector<Message*> outbox_;
    MessageRouter& router_;
    std::mutex session_mutex_;
    uint64_t next_seq_{1};

public:
    ChatSession(MessageRouter& r) : router_(r) {}

    ~ChatSession() {
        std::lock_guard<std::mutex> lock(session_mutex_);
        for (auto* msg : outbox_) {
            delete msg;
        }
    }

    void send_message(const char* data, size_t len) {
        std::lock_guard<std::mutex> lock(session_mutex_);
        auto* msg = new Message(data, len, next_seq_++);
        outbox_.push_back(msg);
        router_.enqueue(msg);
    }

    void flush_delivered() {
        std::lock_guard<std::mutex> lock(session_mutex_);
        // Remove messages that have been successfully routed
        auto it = outbox_.begin();
        while (it != outbox_.end()) {
            if ((*it)->seq_id < next_seq_ - 10) {
                delete *it;
                it = outbox_.erase(it);
            } else {
                ++it;
            }
        }
    }
};

} // namespace rt_chat

int main() {
    using namespace rt_chat;

    CircuitBreaker breaker(3, 2, std::chrono::milliseconds(100));
    MessageRouter router(breaker);
    ChatSession session(router);

    // Simulate chat activity
    for (int i = 0; i < 20; ++i) {
        std::string text = "Hello message " + std::to_string(i);
        session.send_message(text.c_str(), text.size());
    }

    // Process messages through circuit breaker
    for (int round = 0; round < 10; ++round) {
        router.process_batch();
        std::this_thread::sleep_for(std::chrono::milliseconds(50));
    }

    // Flush old messages from session
    session.flush_delivered();

    return 0;
}
